type Shape<T> = { readonly [K in keyof T]: T[K] extends readonly string[] ? readonly string[] : string };

/** Словарь кабинета: набор ключей задаёт русский, узбекский обязан совпасть */
export type VendorDict = Shape<typeof ru>;
export type TextKey = { [K in keyof VendorDict]: VendorDict[K] extends string ? K : never }[keyof VendorDict];

